class iCOM_cat(BaseUIPageObject):
    # application_name = "iCOMCat:localhost:4322"

    # @deco.deco.app_ctx_function()

    def __init__(self, name: str="iCOMCat:127.0.0.1:4322", host: str="127.0.0.1", use_headless_icom: bool=False):
        '''
        Initialises the iCOM_cat() object used for testing with the headless iCOM protocol
        or interacting with the iCOM CAT UI test harness.

        Note: The iCOM DLL path (for headless iCOM testing) is read from the localconfig.cfg file. Ensure that this
        config file is loaded in the top level calling script.

        Args:
            name (str): Name of the iCOM CAT test harness (only needed when interacting with iCOM CAT UI)
            host (str): Host IP address of the iCOM CAT test harness (only needed when interacting with iCOM CAT UI)
            use_headless_icom (bool) - Option to use the headless iCOM protocol for sending Fx or reading Vx values
        '''
        if use_headless_icom:
            logger.info("initialising headless icom")
            self.application_name = "none"
            self.use_headless_icom = True
            self.lib_path = Config.get('run_config.icomdll_path')
            import test
            if self.lib_path == '':
                # Try alternate config
                self.lib_path = Config.get('integrity_config.icomdll_path')
                if self.lib_path == '':
                    self.lib_path = r"C:/Program Files (x86)/Elekta Limited/iCom 14.00/iCOMClient.dll"
            if os.path.isfile(self.lib_path):
                pass
            else:
                self.lib_path = r"D:/squish/iCOMClient.dll"

            # Note: commented out sq.test.log and replaced with logger.info to remove dependency on squishtest.setTestResult()
            #sq.test.log("DLL is:" + self.lib_path) # type:ignore
            logger.info("DLL is:" + self.lib_path)
            self.file_out = r".\fx_vx_out.csv"
            self.vx = IcomVx(self.lib_path)
            self.fx = IcomFx(self.lib_path)

        else:
            self.use_headless_icom = False
            self.application_name = name
            self.application_host = host
            self.use_application()
            try:
                sq.setFocusedWindow(
                    ":Untitled - Unity iCOM Customer Acceptance Test (Not For Clinical Use)_Window_2")
            except Exception:
                try:
                    sq.setFocusedWindow(icom_cat_th_objects.server_Connections_Not_For_Clinical_Use_Dialog)
                except Exception:
                    pass


    @deco.app_ctx_function()
    def set_server_connections(self, lin_id, ip_addr, fx_only=False, vx_only=False):
        '''
        Establishes either Vx only, Fx only or both Vx and Fx connection as an
        external system to the Elekta network communication iCOM interface protocol
        for controlling and monitoring Linac data.

        The iCOM Vx only connection is used when an external system serves as a
        record and verify (R&V) system with the linac.

        The iCOM Vx and iCOM Fx connection is used when an external system is used
        to send a prescription and works as a complete prescription preparation and
        R&V system.

        Args:
            lin_id (str): The Linac ID for this external system to connect to
            ip_addr (str): The Host IP address of the Linac NRT
            fx_only (bool): True to connect to only iCOM Fx
            vx_only (bool): True to connect to only iCOM Vx

        Note: To connect to both fx and vx, set both the fx_only and vx_only parameteres to False

        Returns:
            bool - True if the initial iCOM connection succeeds, False otherwise
        '''
        if self.use_headless_icom:
            try:
                if fx_only:
                    self.fx.connect(hostip=ip_addr, machine=str(lin_id))
                    logger.info("fx-only connected host " + lin_id + ",IP " + ip_addr)
                    return True

                if vx_only:
                    self.vx.connect(hostip=ip_addr, timeout_millis=30000)
                    logger.info("vx-only connected host " + lin_id + ",IP " + ip_addr)
                    return True

                self.vx.connect(hostip=ip_addr, timeout_millis=30000)
                self.fx.connect(hostip=ip_addr, machine=str(lin_id))
                logger.info("vx fx connected host " + lin_id + ",IP " + ip_addr)
                return True
            except Exception as e:
                #test.log("connection error", str(e))    # type:ignore
                logger.error("connection error: " + str(e))
                return False

        self.clear_dialog_popup()
        try:
            try:
                sq.waitForObjectExists(icom_cat_th_objects.server_Connections_Not_For_Clinical_Use_Linac_ID_Edit, 20000)

            except Exception:
                try:
                    try:
                        sq.mouseClick(sq.waitForObject(icom_cat_th_objects.iComCat_dialog_ok_button), 500)

                    except Exception:
                        pass

                    sq.mouseClick(sq.waitForObjectExists(icom_cat_th_objects.o32774_ToolbarItem))
                    sq.snooze(2)
                except Exception:
                    return False

            sq.setFocusedWindow(icom_cat_th_objects.server_Connections_Not_For_Clinical_Use_Dialog)
            split_ip = ip_addr.split(".")

            if(common_pg_obj.set_edit_box(icom_cat_th_objects.server_Connections_Not_For_Clinical_Use_Linac_ID_Edit, lin_id) and
                    common_pg_obj.set_edit_box(icom_cat_th_objects.server_Connections_Not_For_Clinical_Use_Server_IP_Address_Edit_1, split_ip[0]) and
                    common_pg_obj.set_edit_box(icom_cat_th_objects.server_Connections_Not_For_Clinical_Use_Server_IP_Address_Edit_2, split_ip[1]) and
                    common_pg_obj.set_edit_box(icom_cat_th_objects.server_Connections_Not_For_Clinical_Use_Server_IP_Address_Edit_3, split_ip[2]) and
                    common_pg_obj.set_edit_box(icom_cat_th_objects.server_Connections_Not_For_Clinical_Use_Server_IP_Address_Edit_4, split_ip[3])):

                # Get current status of fx/vx server connection checkboxes
                icomcat_fx_checkbox_status = sq.waitForObject(icom_cat_th_objects.iCOMCAT_iCom_Fx_CheckBox)
                icomcat_vx_checkbox_status = sq.waitForObject(icom_cat_th_objects.iCOMCAT_iCom_Vx_CheckBox)

                if fx_only:
                    # Select Fx connection checkbox if not already selected and de-select Vx
                    if not icomcat_fx_checkbox_status.checked:
                        sq.mouseClick(sq.waitForObject(icom_cat_th_objects.iCOMCAT_iCom_Fx_CheckBox))
                    if icomcat_vx_checkbox_status.checked:
                        sq.mouseClick(sq.waitForObject(icom_cat_th_objects.iCOMCAT_iCom_Vx_CheckBox))

                if vx_only:
                    # Select Vx connection checkbox if not already selected and de-select Fx
                    if not icomcat_vx_checkbox_status.checked:
                        sq.mouseClick(sq.waitForObject(icom_cat_th_objects.iCOMCAT_iCom_Vx_CheckBox))
                    if icomcat_fx_checkbox_status.checked:
                        sq.mouseClick(sq.waitForObject(icom_cat_th_objects.iCOMCAT_iCom_Fx_CheckBox))

                # If both fx_only and vx_only arguments are False (default), connect to both Fx and Vx servers
                if not fx_only and not vx_only:
                    if not icomcat_fx_checkbox_status.checked:
                        sq.mouseClick(sq.waitForObject(icom_cat_th_objects.iCOMCAT_iCom_Fx_CheckBox))
                    if not icomcat_vx_checkbox_status.checked:
                        sq.mouseClick(sq.waitForObject(icom_cat_th_objects.iCOMCAT_iCom_Vx_CheckBox))

                sq.mouseClick(sq.waitForObjectExists(icom_cat_th_objects.server_Connections_Not_For_Clinical_Use_OK_Button))
                return True
            else:
                return False

        except Exception:
            return False


    @deco.app_ctx_function()
    def open_file(self, file_name: Union[str, os.PathLike]) -> bool:
        '''
        Creates an iCOM Fx treatment messsge from an efs beam file and inserts
        iCOM Tags, in preparation for a treatment to be sent to the linac.

        Args:
            file_name (path str): File system path to the efs beam file

        Returns:
            bool - True if an iCOM Fx treatment message was successfully created
                   from the efs beam file, False otherwise
        '''
        if self.use_headless_icom:
            try:
                (self.icom_send_msg1, self.icom_tags, self.icom_errors) = self.fx.load_and_create(file_name)
                self.efs_file = file_name
                return True
            except Exception as e:
                logger.exception("Error opening EFS file - " + str(e))
                return False
        try:
            sq.mouseClick(sq.waitForObjectExists(icom_cat_th_objects.o57601_ToolbarItem))
            sq.snooze(1)
            common_pg_obj.set_edit_box(icom_cat_th_objects.EFS_File_Edit, file_name)
            sq.nativeType("<Return>")
            # return True
        except Exception as e:
            logger.exception("Error opening EFS file", str(e))
            sq.saveDesktopScreenshot(sq.squishinfo.resultDir + "\\EFS_Open_Error.png")
            return False
        # acknowledge file not found dialog if it pops up
        try:
            sq.mouseClick(sq.waitForObjectExists(icom_cat_th_objects.oK_Button, 1000))
            sq.mouseClick(sq.waitForObjectExists(":dialog_Cancel_Button", 1000))
            return False
        except Exception:
            return True


    @deco.app_ctx_function()
    def send_field(self) -> Union[Tuple[int, bool], Tuple[Exception, bool], bool]:
        '''
        Sends the treatment settings to the Linac using iCOM Fx.
        Note: The open_file() function needs to be called before send_field()
        to load a beam file first if using the headless option.

        Returns:
            (int, bool) - icom message handle, valid error code or
            (Exception, bool) - Exception if the fx send message failed or
            bool - True if successfully sent using the iCOMCAT UI, False otherwise
        '''
        if self.use_headless_icom:
            logger.info("icom send_field")
            try:
                self.icom_resp_msg1 = self.fx.send_message(self.icom_send_msg1)
                sq.snooze(2)
                self.vx.update_message_list()
                return self.icom_resp_msg1, self.icom_resp_msg1 > 0
            except Exception as e:
                logger.exception("Error send_field - " + str(e))
                return e, False
        try:
            sq.mouseClick(sq.waitForObjectExists(icom_cat_th_objects.iCOM_Send_Field_Button))
            return True
        except Exception:
            return False


    @deco.app_ctx_function()
    def clear_field(self) -> bool:
        '''
        Clears the treatment settings from the linac.

        Returns:
            bool - True if clear settings successful, False otherwise
        '''
        if self.use_headless_icom:
            try:
                return self.fx.send_cancel()
            except Exception as e:
                logger.exception("Clear field fx.delete_message exception", str(e))
                return False
        try:
            sq.mouseClick(sq.waitForObjectExists(
                ":Untitled - Unity iCOM Customer Acceptance Test (Not For Clinical Use).Clear Field_Button"))
            return True
        except Exception as e:
            logger.exception("Clear field button not clicked", str(e))
            return False


    @deco.app_ctx_function()
    def confirm_settings(self):
        '''
        Confirms the linac settings and clears the "Settings Not Confirmed"
        inhibit to allow beam delivery treatment to start.

        Returns:
            bool - True if confirm settings successful, False otherwise
        '''
        if self.use_headless_icom:
            try:
                confirm = sq.waitFor(
                    "self.vx.get_next_message().get_machine_state()in ['CONFIRM SETTINGS','READY TO START']", 5000)
                if confirm:
                    return self.fx.send_confirm()
                else:
                    logger.info(
                        "Failed to reach Confirm Settings state.Current State is " +
                        self.vx.get_next_message().get_machine_state())
                    return False
            except Exception as e:
                logger.exception("Error confirm_settings - " + str(e))
                return False
        try:
            sq.mouseClick(sq.waitForObjectExists(icom_cat_th_objects.iCOM_Confirm_Settings_Button))
            return True
        except Exception:
            return False


    @deco.app_ctx_function()
    def unconfirm_settings(self) -> bool:
        '''
        Unconfirms the linac settings and reinstates the "Settings Not Confirmed"
        inhibit to prevent beam delivery treatment to start.

        Returns:
            bool - True if unconfirm settings successful, False otherwise
        '''
        if self.use_headless_icom:
            try:
                self.fx.send_unconfirm()
                return True
            except Exception as e:
                logger.exception("Error unconfirm_settings - " + str(e))
                return False
        try:
            sq.mouseClick(sq.waitForObjectExists(icom_cat_th_objects.iCOM_Unconfirm_Settings_Button))
            return True
        except Exception:
            return False


    @deco.app_ctx_function()
    def check_fx_connection(self) -> bool:
        '''
        Checks the iCOM Fx connection state for the current iCOM object

        Returns:
            bool - True if connection successful, False otherwise
        '''
        if self.use_headless_icom:
            try:
                # using the same method for both fx anx vx
                return self.fx.connection_state_ok()
            except Exception as e:
                logger.exception("Error check_fx_connection - " + str(e))
                return False
        try:
            sq.waitForObjectExists(icom_cat_th_objects.fx_Connected_StatusBarItem, 0)
            return True
        except Exception:
            return False


