    @deco.app_ctx_function()
    def get_Fx_patient_id(self) -> opt[str]:
        '''
        Reads the value of the Patient ID from the the treatment message
        sent to the Linac using the iCOM Fx headless interface

        Returns:
            str - Value of the patient ID in the iCOM Fx treatment sent
        '''
        if self.use_headless_icom:
            try:
                return self.icom_tags[defn_to_tag_map['PatientId'] + '-0'][1]
            except Exception as e:
                logger.exception("Error get_Fx_patient_id - " + str(e))
                # return "False"
                # Makes it easier to compare when efs files have no entry
                return None
        try:
            return common_pg_obj.get_object_text(icom_cat_th_objects.iCom_Fx_Patient_id)
        except Exception:
            return None


