    def get_Fx_electron_applicator(self) -> opt[str]:
        '''
        Reads the value of the Electron applicator from the the treatment message
        sent to the Linac using the iCOM Fx headless interface

        Returns:
            str - Value of the Electron applicator in the iCOM Fx treatment sent
        '''
        if self.use_headless_icom:
            # Note: Python is case sensitive. The hex values defined in defn_to_tag_map are upper case, but the hex
            # values in icom_tags dictionary are lower case. Convert defn_to_tag_map hex values to lower case.
            try:
                return self.icom_tags[defn_to_tag_map['ElectronAppCode'].lower() + '-1'][1]
            except Exception as e:
                logger.exception("Error get_Fx_electron_applicator - " + str(e))
                # return "False"
                # Makes it easier to compare when efs files have no entry
                return None


