    @deco.app_ctx_function()
    def get_Vx_terminates(self) -> List[str]:
        '''
        Reads the current list of Terminate reasons from the linac using the
        iCOM Vx headless interface.

        Returns:
            List[str] - List of Terminate reasons
        '''
        if self.use_headless_icom:
            try:
                self.vx.update_message_list()
                last_vx_msg = self.vx.message_list[-1]._rawmsg
                all_inhibits = [last_vx_msg[key]['R'] for key in last_vx_msg.keys() if re.match(r'TerminateReason|TerminateReason*', key)]
                return [i for i in all_inhibits if re.match(r'[a-zA-Z]', i)]
            except Exception:
                return ["False"]
        else:
            list_of_terminates = sq.object.children(sq.findObject(icom_cat_th_objects.iCom_Vx_Terminates))
            terminates = []
            # Due to some unknown reason the blank list items are not empty but filled
            # with 11 character spaces exactly, hence to counter that
            for i in list_of_terminates:
                if len(i["text"]) != 11:
                    terminates.append(i["text"])
            return terminates


    @deco.app_ctx_function()
    def check_delivered_MU(self, MU_to_check: str) -> bool:
        '''
        Reads the current Delivered MU from the linac using the iCOM Vx headless
        interface and compare it against an expected MU_to_check value

        Args:
            MU_to_check (str): Expected MU to be checked against the delivered MU

        Returns:
            bool - True if the delivered MU matches the expected value, False
            if it doesn't match or the delivered MU cannot be read
        '''
        if self.use_headless_icom:
            self.vx.update_message_list()
            try:
                return MU_to_check == self.vx.message_list[-1].get_prescribed_by_tagname('BeamMonitorUnits')
            except Exception as e:
                logger.exception("Error check_delivered_MU - " + str(e))
                return False
        try:
            delivered_MU = common_pg_obj.get_object_text(icom_cat_th_objects.iCom_Delivered_MU)
            if delivered_MU == MU_to_check:
                return True
            else:
                return False
        except Exception:
            return False


