    def get_Vx_gantry_angle(self, mode: str="run", align_with_ui=False) -> opt[float]:
        '''
        Reads the current Gantry value from the linac using the
        iCOM Vx headless interface.

        Note: Negative Gantry angles obtained from the iCOM interface are not displayed
        on the Integrity REP UI screen. Instead, the corresponding positive value is
        displayed on the UI, along with the direction (clockwise/ counterclockwise).
        To obtain the value as displayed on the Integrity REP UI screen, set the
        align_with_ui argument to True.

        Args:
            mode (str): Parameter mode (set or run) iCOM Vx value to
            read. Note: The run value is displayed as the ACTUAL value
            on the Integrity UI.
            align_with_ui (bool): Set to True to return the corresponding positive
            gantry angle for a negative angle, as per the display on the Integrity
            REP UI screen.

        Returns:
            float or None - Gantry value or None
        '''
        if not self.use_headless_icom:
            raise ValueError("This function explicitly uses the headless icom interface.\
                Please ensure the use_headless_icom arg is set to True when creating the iCOM_cat() object")
        self.vx.update_message_list()
        try:
            if mode == "set":
                set_value = self.vx.message_list[-1].get_set_by_tagname('GantryAngle')
                if set_value:
                    if align_with_ui:
                        return convert_negative_angle(float(set_value))
                    return float(set_value)
            elif mode == "run":
                run_value = self.vx.message_list[-1].get_run_by_tagname('GantryAngle')
                if run_value:
                    if align_with_ui:
                        return convert_negative_angle(float(run_value))
                    return float(run_value)
            else:
                logger.info("Vx gantry angle invalid mode entered")
                return None
        except Exception as e:
            logger.exception("Error get_Vx_gantry_angle - " + str(e))
            return None


