    def get_Vx_table_vertical(self, mode: str="run", align_with_ui=False) -> opt[float]:
        '''
        Reads the current Table Vertical (height) value from the linac using the
        iCOM Vx headless interface.

        Note: The Table Vertical value sign is inverted (i.e. negative value is displayed
        as positive and vice versa) when displayed on the Integrity REP UI screen. To
        obtain the value as displayed on the Integrity REP UI screen, set the
        align_with_ui argument to True.

        Args:
            mode (str): Parameter mode (set or run) iCOM Vx value to
            read. Note: The run value is displayed as the ACTUAL value
            on the Integrity UI.
            align_with_ui (bool): Set to True to flip the sign (positive/ negative) of the
            returned table vertical value, as per the display on the Integrity REP screen.

        Returns:
            float or None - Table Vertical (height) value or None
        '''
        if not self.use_headless_icom:
            raise ValueError("This function explicitly uses the headless icom interface.\
                Please ensure the use_headless_icom arg is set to True when creating the iCOM_cat() object")
        try:
            self.vx.update_message_list()
            if mode == "set":
                set_value = self.vx.message_list[-1].get_set_by_tagname('TableHeight')
                if set_value and not set_value.isspace():
                    if align_with_ui:
                        return flip_number_sign(float(set_value))
                    return float(set_value)
                else:
                    return None
            elif mode == "run":
                run_value = self.vx.message_list[-1].get_run_by_tagname('TableHeight')
                if run_value and not run_value.isspace():
                    if align_with_ui:
                        return flip_number_sign(float(run_value))
                    return float(run_value)
                else:
                    return None
            else:
                logger.info("Vx table vertical Invalid mode entered")
                return None
        except Exception as e:
            logger.exception("Error get_Vx_table_vertical - " + str(e))
            return None


